import{_ as t,o as s,c as a,a3 as o}from"./chunks/framework.D1GAkLkK.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"troubleshooting.md","filePath":"troubleshooting.md"}'),n={name:"troubleshooting.md"};function r(i,e,d,h,c,l){return s(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><p><code>opstruss doctor</code> checks what a run of the stack needs on this machine: the programs of each unit and task, the age key, sops, and the filesystem of <code>.opstruss/</code>. Start there.</p><h2 id="a-program-is-not-in-path" tabindex="-1">A program is not in PATH <a class="header-anchor" href="#a-program-is-not-in-path" aria-label="Permalink to &quot;A program is not in PATH&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>default/infra: error: plugin cat.tofu requires jq, which is not in PATH</span></span></code></pre></div><p>Install the program, for example with <code>mise use jq</code>, or put the directory that has it in <code>PATH</code>. <code>opstruss doctor</code> shows where each program is found. The <a href="./getting-started/install#requirements">Install</a> page lists what each plugin needs.</p><h2 id="a-unit-is-pending-after-a-crash" tabindex="-1">A unit is pending after a crash <a class="header-anchor" href="#a-unit-is-pending-after-a-crash" aria-label="Permalink to &quot;A unit is pending after a crash&quot;">​</a></h2><p>When OpsTruss is killed during a run, the record of a unit that was running keeps a <code>pending</code> mark. The next run waits for the programs of the old run to end and runs the unit again; <code>status</code> shows the mark until then. A run that cannot list processes, as in some sandboxes, cannot wait, so the unit fails until it runs where it can.</p><h2 id="another-run-holds-a-lock" tabindex="-1">Another run holds a lock <a class="header-anchor" href="#another-run-holds-a-lock" aria-label="Permalink to &quot;Another run holds a lock&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>default/web: waiting for the lock held by run 20261027T124725Z-0069f2ad (pid 4121 on build-1, for 12s)</span></span></code></pre></div><p>Each unit has a lock, so two runs never change it at once. Let the other run end, or cancel it with <code>opstruss runs cancel &lt;run&gt;</code>.</p><h2 id="context-changed" tabindex="-1">context changed <a class="header-anchor" href="#context-changed" aria-label="Permalink to &quot;context changed&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>default/dns: error: context changed: AWS_PROFILE differs from the record, whose destroy reaches the old target; up --force moves the unit and forgets that target</span></span></code></pre></div><p>A variable that <code>pass:</code> lets through, such as <code>AWS_PROFILE</code>, differs from the one the unit was made with. Set it back, or run <code>up --force</code> to move the unit to the new target. A credential that changes every session belongs in <code>secrets:</code> instead: <a href="./guides/secrets#variables-for-the-tools-in-plugins">Secrets with sops</a>.</p><h2 id="a-trigger-does-not-run" tabindex="-1">A trigger does not run <a class="header-anchor" href="#a-trigger-does-not-run" aria-label="Permalink to &quot;A trigger does not run&quot;">​</a></h2><p><code>opstruss list</code> says when no daemon runs the triggers, and why the last <code>up</code> could not install them, such as a secret that is not set. Start the daemon with <code>opstruss up -d</code>, from a shell with the same environment each time. The daemon writes what it does to <code>.opstruss/logs/&lt;stack&gt;/_daemon.jsonl</code>.</p><h2 id="the-daemon-runs-an-older-opstruss" tabindex="-1">The daemon runs an older OpsTruss <a class="header-anchor" href="#the-daemon-runs-an-older-opstruss" aria-label="Permalink to &quot;The daemon runs an older OpsTruss&quot;">​</a></h2><p>After an upgrade, a daemon keeps the binary that started it. Run <code>opstruss stop</code>, then <code>opstruss up -d</code>.</p><h2 id="a-stack-is-gone-from-stacks" tabindex="-1">A stack is gone from stacks: <a class="header-anchor" href="#a-stack-is-gone-from-stacks" aria-label="Permalink to &quot;A stack is gone from stacks:&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stack default has 3 records, but the project does not declare it; opstruss destroy --stack default takes them down</span></span></code></pre></div><p>A stack keeps its records after the project stops declaring it. <code>opstruss destroy --stack default</code> takes its units down from the records; <code>opstruss state list --stack default</code> shows them.</p><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck&quot;">​</a></h2><p><code>opstruss runs &lt;run&gt;</code> shows every event of a run, and <code>OPSTRUSS_LOG=debug</code> adds the diagnostics of the engine. Search the <a href="https://github.com/opstruss/opstruss/issues" target="_blank" rel="noreferrer">issues</a>, or open one with the output of <code>opstruss version</code> and the smallest <code>opstruss.yaml</code> that shows the problem, without secrets.</p>',22)])])}const g=t(n,[["render",r]]);export{p as __pageData,g as default};
